 ctx.strokeStyle=line.color;ctx.lineWidth=5;ctx.lineJoin='round';ctx.beginPath();line.stations.forEach((s,i)=>{const p=points[s.id];if(i)ctx.lineTo(p.x,p.y);else ctx.moveTo(p.x,p.y);});ctx.stroke();
