function renderList(){for(const l of [1,8])$('line'+l).classList.toggle('active',l===currentLine);$('station-count').textContent=engine.lines[currentLine].stations.length;$('station-list').innerHTML=engine.lines[currentLine].stations.map((s,i)=>`<button class="station-row ${s.id===selectedStation?'selected':''}" data-id="${s.id}"><span class="number">${String(i+1).padStart(2,'0')}</span><span class="route-dot" style="border-color:${engine.lines[currentLine].color}"></span><span>${s.nombre}</span>${s.terminal?'<small>Terminal</small>':''}</button>`).join('');document.querySelectorAll('.station-row').forEach(b=>b.onclick=()=>{selectedStation=b.dataset.id;$('follow-train').checked=false;window.stationScene?.setCamera(window.stationScene.cameraMode==='platform'?'platform':'full');renderList();renderDetails();draw();});}
