 canvas.onclick=e=>{const r=canvas.getBoundingClientRect(),[mw,mh]=mapSize(),x=currentLine===8?((e.clientX-r.left)*canvas.width/r.width-mapTransform8.x)/mapTransform8.scale:(e.clientX-r.left)*mw/r.width,y=currentLine===8?((e.clientY-r.top)*canvas.height/r.height-mapTransform8.y)/mapTransform8.scale:(e.clientY-r.top)*mh/r.height;const train=engine.trains.filter(t=>t.line===currentLine).find(t=>{const p=trainPoint(t);return Math.hypot(p.x-x,p.y-y)<(currentLine===8?23:18);});if(train){window.selectSceneTrain(train.id,{fromMap:true});return;}let closest=null,d=currentLine===8?18:35;for(const s of data.estaciones.filter(s=>s.linea===currentLine)){const p=points[s.id],n=Math.hypot(p.x-x,p.y-y);if(n<d){closest=s;d=n;}}if(closest){if(closest.linea!==currentLine)lineSelect(closest.linea);selectedStation=closest.id;$('follow-train').checked=false;window.stationScene?.setCamera(window.stationScene.cameraMode==='platform'?'platform':'full');renderList();renderDetails();draw();}};
